#include <stdio.h>
#include <string.h>

#define MAX(a, b) ((a) > (b) ? (a) : (b))
#define MIN(a, b) ((a) < (b) ? (a) : (b))

#define MAX_N 100
#define MAX_M 100

int n, m;

void parse2D(char *s, int matrix[MAX_N][MAX_M]);
void parse1D(char *s, int array[MAX_M]);

int main() {
    char s[100000];
    scanf("%s", s);

    int matrix[MAX_N][MAX_M];
    // 输入二维数组字符串解析
    parse2D(s, matrix);

    // 本题N和M取值是[0,100]，如果N或M取0的话，则本题没有结果，理论上应该不会出现这种情况，因为题目也没说
    if (n == 0 || m == 0) {
        puts("-1");
        return 0;
    }

    // 取矩阵第一行作为每列的基准值
    int *cols_max_value = matrix[0];

    // 从矩阵第二行开始遍历
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < m; j++) {
            // 保留每列的最大值
            cols_max_value[j] = MAX(cols_max_value[j], matrix[i][j]);
        }
    }

    // 取每列最大值中的最小值
    int min = cols_max_value[0];
    for (int i = 1; i < m; i++) {
        min = MIN(min, cols_max_value[i]);
    }

    printf("%d\n", min);

    return 0;
}

void parse2D(char *s, int matrix[MAX_N][MAX_M]) {
    unsigned long long len = strlen(s);

    int i = 0;

    char *start = s + 2;
    char *end = strstr(start, "],[");

    while (end != NULL) {
        char subStr[len];
        memset(subStr, '\0', len);

        strncpy(subStr, start, end - start);

        parse1D(subStr, matrix[i]);
        i++;

        start = end + 3;
        end = strstr(start, "],[");
    }

    char subStr[len];
    memset(subStr, '\0', len);

    strncpy(subStr, start, (s + len - 2) - start);
    parse1D(subStr, matrix[i]);
    n = i + 1;
}

void parse1D(char *s, int array[MAX_M]) {
    int j = 0;

    char *token = strtok(s, ",");
    while (token != NULL) {
        int num;
        sscanf(token, "%d", &num);

        array[j++] = num;

        token = strtok(NULL, ",");
    }

    m = j;
}
